solutionCode:
class Motor(val name: String, val speed: Double)

fun main() {
    val left = Motor("Left Drive", 0.6)
    val right = Motor("Right Drive", 0.9)
    println("${left.name}: ${left.speed}")
    println("${right.name}: ${right.speed}")
}
